    "remediation_plan": {
        "plan_description": "Disabling IPv6 router acceptance is a standard networking hardening step that does not affect authentication, authorization, or filesystem integrity. The change is made via sysctl and persisted in /etc/sysctl.d, which is low risk and easily reversible.",
        "commands": [
            {
                "command": "sysctl -w net.ipv6.conf.all.accept_ra=0"
            }
        ],
        "files": [
            {
                "path": "/etc/sysctl.d/99-sysctl.conf",
                "content": "net.ipv6.conf.all.accept_ra = 0",
                "mode": "0644"
            }
        ]
    }
}

